import React, { useState } from 'react';
import axios from 'axios';

function FeedbackForm() {
  const [form, setForm] = useState({ name: '', email: '', category: '', text: '' });

  const handleChange = e => {
    setForm({ ...form, [e.target.name]: e.target.value });
  };

  const handleSubmit = async e => {
    e.preventDefault();
    await axios.post('http://localhost:5000/api/feedback', form);
    alert('Feedback submitted!');
    setForm({ name: '', email: '', category: '', text: '' });
  };

  return (
    <form onSubmit={handleSubmit}>
      <h2>Submit Feedback</h2>
      <input name="name" placeholder="Name" value={form.name} onChange={handleChange} required /><br />
      <input name="email" placeholder="Email" value={form.email} onChange={handleChange} required /><br />
      <select name="category" value={form.category} onChange={handleChange} required>
        <option value="">Select Category</option>
        <option value="Suggestion">Suggestion</option>
        <option value="Bug Report">Bug Report</option>
        <option value="Feature Request">Feature Request</option>
      </select><br />
      <textarea name="text" placeholder="Your Feedback" value={form.text} onChange={handleChange} required></textarea><br />
      <button type="submit">Submit</button>
    </form>
  );
}

export default FeedbackForm;
